WITH payload AS (SELECT value AS j FROM jsonb_array_elements($PAYLOAD$[{"order":26,"title":"القراءة: نزهة في أحضان الطبيعة","content":"القراءة: نزهة في أحضان الطبيعة\n\nأهداف التعلّم\n• يقرأ نصًا وصفيًا أصليًا ويستخرج تفاصيل المكان.\n• يميّز فعلًا يدل على مسؤولية الزائر.\n• يكتب انطباعًا قصيرًا عن بيئة طبيعية.\n\nالشرح التعليمي الأصلي\nنقرأ مشهدًا أصليًا لا يطابق نص الكتاب: «خرجت هدى مع أسرتها إلى حديقة عامة صباحًا. لاحظت الأشجار والطيور ومسار المشي. بعد تناول الطعام جمعت الأسرة مخلفاتها في كيس مخصص، وتركت المكان نظيفًا ليستمتع به زوار آخرون. قالت هدى: جمال الطبيعة يحتاج منا إلى عناية لا إلى مديح فقط». تتسلسل الأحداث من الزيارة إلى المحافظة على المكان، ونستنتج أن احترام البيئة مسؤولية مشتركة.\n\nأمثلة في السياق\nتفصيل حسي: صوت الطيور. سلوك عملي: جمع المخلفات. فكرة النص: الاستمتاع بالطبيعة لا ينفصل عن حمايتها.\n\nالتدريبات الفردية\nمتى خرجت الأسرة؟ اذكر عنصرين طبيعيين في الحديقة. ما الدليل على احترام الزوار الآخرين؟ اكتب أربعة أسطر تصف زيارة مشابهة دون نقل النص حرفيًا.\n\nمفتاح الإجابة والتغذية الراجعة\nصباحًا؛ الأشجار والطيور؛ ترك المكان نظيفًا؛ تقبل أوصاف شخصية مترابطة تُظهر المكان والفعل والشعور.\n\nتطبيق من الحياة اليومية\nدوّن قاعدة واحدة تساعدك عند زيارة حديقة أو ساحل، وطبّقها فعلًا في الرحلة المقبلة.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يقرأ نصًا وصفيًا أصليًا ويستخرج تفاصيل المكان.","يميّز فعلًا يدل على مسؤولية الزائر.","يكتب انطباعًا قصيرًا عن بيئة طبيعية."],"vocabulary":[{"word":"مسار","meaning":"طريق محدد للمشي"},{"word":"مخلفات","meaning":"أشياء تُترك بعد الاستخدام"}],"quiz":{"prompt":"كيف حافظت الأسرة على الحديقة؟","options":["جمعت مخلفاتها","تركت العبوات","قطفت الأشجار","أزعجت الزوار"],"correct":"جمعت مخلفاتها"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":27,"title":"القواعد النحوية: الأسماء المجرورة بحروف الجر","content":"القواعد النحوية: الأسماء المجرورة بحروف الجر\n\nأهداف التعلّم\n• يتعرف حروف الجر الأساسية في جمل ذات معنى.\n• يحدد الاسم المجرور وحركته في مثال مفرد.\n• يصوغ عبارتين صحيحتين عن المكان والاتجاه.\n\nالشرح التعليمي الأصلي\nتدخل حروف الجر على الأسماء فتجعلها مجرورة: من، إلى، عن، على، في، الباء، اللام والكاف في مواضعها. في «ذهبتُ إلى المكتبةِ» الاسم «المكتبةِ» مجرور بـ«إلى» وعلامة جره الكسرة؛ وفي «جلستُ على المقعدِ» المقعدِ اسم مجرور. وقد تكون علامة الجر الياء في المثنى أو جمع المذكر السالم مثل «مررتُ بالمعلمينَ». نميز الحرف عن الاسم الذي يليه ولا نغير رسم الحرف نفسه.\n\nأمثلة في السياق\n«في القاعةِ» جار ومجرور. «من المنزلِ إلى السوقِ» حرفا جر ويتبعهما اسمان مجروران.\n\nالتدريبات الفردية\nحدد الاسم المجرور في «وضعت الملفَّ في الحقيبةِ». اضبط «على المكتب» ضبطًا صحيحًا. كوّن جملة تستخدم فيها «من» للابتداء.\n\nمفتاح الإجابة والتغذية الراجعة\nالحقيبةِ؛ على المكتبِ؛ مثال «سرت من المنزلِ إلى المركزِ».\n\nتطبيق من الحياة اليومية\nاكتب تعليمات مسار إلى غرفة الاستقبال باستخدام «إلى» و«في»، ثم ضع كسرة المجرور المفرد.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يتعرف حروف الجر الأساسية في جمل ذات معنى.","يحدد الاسم المجرور وحركته في مثال مفرد.","يصوغ عبارتين صحيحتين عن المكان والاتجاه."],"vocabulary":[{"word":"حرف جر","meaning":"حرف يجر الاسم بعده"},{"word":"الكسرة","meaning":"علامة الجر الأصلية للاسم المفرد"}],"quiz":{"prompt":"ما الاسم المجرور في «أضعُ الكتابَ على الرفِّ»؟","options":["الرفِّ","الكتابَ","أضعُ","على"],"correct":"الرفِّ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":28,"title":"الإملاء: الهمزة المتوسطة المكسورة (1)","content":"الإملاء: الهمزة المتوسطة المكسورة (1)\n\nأهداف التعلّم\n• يميز الهمزة المتوسطة المكسورة عن المفتوحة.\n• يستنتج أن الكسرة أقوى الحركات عند رسم الهمزة.\n• يكتب كلمات «سُئِل» و«رَئِيس» كتابة سليمة.\n\nالشرح التعليمي الأصلي\nمن أسس كتابة الهمزة المتوسطة مقارنة حركة الهمزة بحركة الحرف السابق. الكسرة أقوى من الضمة والفتحة والسكون، ويناسبها كرسي الياء (ئ). في «سُئِلَ» الهمزة مكسورة وما قبلها مضموم، فتكتب على ياء. وفي «رَئِيس» الهمزة مكسورة وما قبلها مفتوح، فتكتب على ياء أيضًا. ننتبه إلى شكل الكلمة قبل التسرع في الرسم، ولا نضيف نقطتين مستقلتين إلى كرسي الهمزة.\n\nأمثلة في السياق\n«سُئِلَ الرجلُ عن الموعد» و«رَئِيس القسمِ حاضرٌ» تشتملان همزة متوسطة مكسورة مرسومة على ياء.\n\nالتدريبات الفردية\nحدد حركة الهمزة في «رئيس». اختر رسم «سُئِل / سُؤِل» في البناء للمجهول. اكتب جملة تستخدم فيها «رئيس» مع الضبط إن استطعت.\n\nمفتاح الإجابة والتغذية الراجعة\nالهمزة مكسورة؛ «سُئِلَ»؛ مثال «رئيسُ الفريقِ حاضرٌ».\n\nتطبيق من الحياة اليومية\nإذا وردت كلمة «رئيس» في رسالة رسمية، راجع موضع الهمزة على ياء قبل إرسالها.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز الهمزة المتوسطة المكسورة عن المفتوحة.","يستنتج أن الكسرة أقوى الحركات عند رسم الهمزة.","يكتب كلمات «سُئِل» و«رَئِيس» كتابة سليمة."],"vocabulary":[{"word":"كسرة","meaning":"حركة قصيرة أقوى الحركات في رسم الهمزة"},{"word":"نبرة الهمزة","meaning":"كرسي الياء الذي يحمل الهمزة"}],"quiz":{"prompt":"لماذا رُسمت همزة «سُئِلَ» على ياء؟","options":["لأن الهمزة مكسورة","لأنها في آخر الكلمة","لأنها ساكنة بعد ألف","لأن الكلمة لا حركة فيها"],"correct":"لأن الهمزة مكسورة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":29,"title":"الإنتاج الكتابي: المذكرات اليومية (3)","content":"الإنتاج الكتابي: المذكرات اليومية (3)\n\nأهداف التعلّم\n• يحرر مذكرة فيها حدث وشعور وتأمل شخصي.\n• يراجع التسلسل الزمني للأحداث.\n• يحذف تفصيلًا خاصًا غير ضروري من مذكرة يشاركها.\n\nالشرح التعليمي الأصلي\nفي تطوير المذكرات اليومية ننتقل من ذكر الحدث إلى فهم أثره والتخطيط للمستقبل. مثال أصلي: «الثلاثاء: وصلت إلى مركز التعلم مبكرًا. قرأت الإعلان على الباب دون مساعدة للمرة الأولى. شعرت بالثقة لأنني كنت أتدرب طوال الأسبوع. سأكرر قراءة اللوحات في الأماكن العامة». تتضمن المذكرة تاريخًا تقريبيًا وحدثًا يمكن وصفه وشعورًا وقرارًا. عند مشاركة المذكرة نحذف ما قد يمس خصوصية الزملاء.\n\nأمثلة في السياق\nحدث: قراءة الإعلان. أثر: زيادة الثقة. خطة: ممارسة القراءة في الحياة اليومية.\n\nالتدريبات الفردية\nرتب من المثال: الحدث، الشعور، القرار. اكتب مذكرة من خمس جمل عن تجربة تعلم، ثم احذف منها معلومة تخص شخصًا آخر دون إذنه.\n\nمفتاح الإجابة والتغذية الراجعة\nالحدث أولًا ثم الشعور ثم القرار؛ تقبل مذكرة شخصية ذات زمن واضح وتسلسل صحيح وتحترم خصوصية الآخرين.\n\nتطبيق من الحياة اليومية\nاكتب في نهاية كل أسبوع إنجازًا واحدًا وتحديًا واحدًا وخطوة للتعلم دون المبالغة في وصف نفسك.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحرر مذكرة فيها حدث وشعور وتأمل شخصي.","يراجع التسلسل الزمني للأحداث.","يحذف تفصيلًا خاصًا غير ضروري من مذكرة يشاركها."],"vocabulary":[{"word":"تأمل","meaning":"تفكير في معنى التجربة"},{"word":"خصوصية","meaning":"حق الشخص في حماية معلوماته"}],"quiz":{"prompt":"أي عنصر يطوّر المذكرة من سرد بسيط إلى تأمل؟","options":["ما تعلمه الكاتب من التجربة","رقم غير موثق","حذف التاريخ","تكرار الحدث وحده"],"correct":"ما تعلمه الكاتب من التجربة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":30,"title":"القراءة: بيئتنا حياتنا - دراسة القصيدة كاملة، والحفظ من 1 إلى 6","content":"القراءة: بيئتنا حياتنا - دراسة القصيدة كاملة، والحفظ من 1 إلى 6\n\nأهداف التعلّم\n• يفهم فكرة المسؤولية البيئية في نص أصلي مستقل.\n• يحدد سببًا ونتيجة في موقف عن النظافة.\n• يميز التمرين الأصلي من القصيدة الرسمية التي لم يُتحقق من متنها.\n\nالشرح التعليمي الأصلي\nخطة الدرس تتضمن قصيدة «بيئتنا حياتنا» ودراسة القصيدة كاملة وحفظ الأبيات 1–6. لا يتوفر لدينا فهرس ومتن موثقان هنا، ولذلك لا ننسب أبياتًا إلى الكتاب. نقدم بدلًا من ذلك نصًا داعمًا من تأليف ضاديوم: «رأى عادل ورقة على الأرض في ساحة مركز التعلم. وضعها في السلة، ثم اقترح على زملائه توزيع السلال قرب المداخل. لاحظ الجميع أن ترتيب المكان يجعل الحركة أكثر راحة ويحمي المنظر العام». نستخرج علاقة السبب والنتيجة ونستعد لاحقًا لدراسة القصيدة الأصلية عند التحقق منها.\n\nأمثلة في السياق\nسبب: وضع السلال في مواضع مناسبة. نتيجة متوقعة: سهولة التخلص من المخلفات. العبارة «بيئتنا حياتنا» تؤكد الصلة بين جودة البيئة وحياة الناس.\n\nالتدريبات الفردية\nاذكر المبادرة التي اقترحها عادل. استنتج نتيجة للالتزام بها. اكتب عبارة إرشادية من سطر واحد عن نظافة المكان. لا تبدأ بحفظ أبيات على أنها مقررة دون المصدر الرسمي.\n\nمفتاح الإجابة والتغذية الراجعة\nاقترح توزيع السلال قرب المداخل؛ تقليل المخلفات وتيسير التخلص منها؛ مثال «حافظ على نظافة المكان ليستفيد الجميع».\n\nتطبيق من الحياة اليومية\nشارك في مبادرة بسيطة لتنظيف مساحة عامة دون التعامل مع مواد حادة أو خطرة، واستعن بالمختصين إذا وجدت مخلفات مؤذية.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يفهم فكرة المسؤولية البيئية في نص أصلي مستقل.","يحدد سببًا ونتيجة في موقف عن النظافة.","يميز التمرين الأصلي من القصيدة الرسمية التي لم يُتحقق من متنها."],"vocabulary":[{"word":"مبادرة","meaning":"عمل إيجابي يبدأ باقتراح وتنفيذ"},{"word":"نتيجة","meaning":"أثر ينشأ عن سبب"}],"quiz":{"prompt":"ما حالة أبيات القصيدة المقررة في هذه المسودة؟","options":["لم تتم مطابقتها بمصدر رسمي بعد","حُفظت من الكتاب مباشرة","مراجعة نهائيًا","نُقلت حرفيًا هنا"],"correct":"لم تتم مطابقتها بمصدر رسمي بعد"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":31,"title":"القواعد النحوية: الأسماء المجرورة بالإضافة","content":"القواعد النحوية: الأسماء المجرورة بالإضافة\n\nأهداف التعلّم\n• يميز المضاف والمضاف إليه في أربع تراكيب.\n• يعرب مضافًا إليه مفردًا بالكسرة.\n• يفرق بين الإضافة والجار والمجرور.\n\nالشرح التعليمي الأصلي\nالإضافة تركيب بين اسمين يوضح علاقة أحدهما بالآخر، ويكون الاسم الثاني «مضافًا إليه» مجرورًا. في «كتابُ الطالبِ» كلمة «كتابُ» مضاف بحسب موقعها، و«الطالبِ» مضاف إليه مجرور بالكسرة. لا نضع حرف جر بين الاسمين في المثال. قد يكون المضاف منصوبًا أو مرفوعًا أو مجرورًا بحسب الجملة، لكن المضاف إليه مجرور دائمًا. «بابُ المركزِ مفتوحٌ» مثال مناسب من الحياة اليومية.\n\nأمثلة في السياق\n«عنوانُ الرسالةِ واضحٌ»: الرسالةِ مضاف إليه. «ذهبت إلى المركزِ» جار ومجرور وليس إضافة.\n\nالتدريبات الفردية\nحدد المضاف إليه في «نافذةُ الصفِّ مفتوحةٌ». كوّن تركيبًا بإضافة «المكتبِ» إلى «بابُ». ضع حركة الاسم الثاني في «وقتُ الدرس».\n\nمفتاح الإجابة والتغذية الراجعة\nالصفِّ؛ بابُ المكتبِ؛ وقتُ الدرسِ.\n\nتطبيق من الحياة اليومية\nاكتب ثلاثة تراكيب تساعدك على وصف مقتنيات المنزل أو المستندات: رقمُ الهاتفِ، موعدُ اللقاءِ، عنوانُ المركزِ.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز المضاف والمضاف إليه في أربع تراكيب.","يعرب مضافًا إليه مفردًا بالكسرة.","يفرق بين الإضافة والجار والمجرور."],"vocabulary":[{"word":"إضافة","meaning":"تركيب يربط اسمًا باسم"},{"word":"مضاف إليه","meaning":"اسم مجرور يأتي بعد المضاف"}],"quiz":{"prompt":"ما المضاف إليه في «موعدُ الدرسِ قريبٌ»؟","options":["الدرسِ","موعدُ","قريبٌ","لا يوجد"],"correct":"الدرسِ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":32,"title":"الإملاء: الهمزة المتوسطة المكسورة (2)","content":"الإملاء: الهمزة المتوسطة المكسورة (2)\n\nأهداف التعلّم\n• يراجع قاعدة الهمزة المكسورة في ثلاثة سياقات.\n• يصحح أخطاء شائعة في «بئر» و«فئة».\n• يوظف كلمات بهمزة على نبرة في جمل من إنشائه.\n\nالشرح التعليمي الأصلي\nفي التدريب الثاني نتعامل مع الهمزة المكسورة بعد السكون أو الفتحة، مع النظر دائمًا إلى أقوى الحركتين. نقول «بِئْر» حيث همزتها ساكنة وما قبلها مكسور، فترسم على ياء لقوة الكسرة، بينما في «فِئَة» الهمزة مفتوحة وما قبلها مكسور فترسم كذلك على ياء. وفي «سُئِلَ» الهمزة مكسورة بعد ضمة. هذه ثلاث حالات مختلفة تصل كلها إلى الكرسي نفسه، فلا يكفي حفظ شكل الكلمة من غير تفسير.\n\nأمثلة في السياق\nبئر: ما قبل الهمزة مكسور. فئة: ما قبل الهمزة مكسور. سئل: الهمزة مكسورة.\n\nالتدريبات الفردية\nاشرح سبب رسم همزة «بئر» على ياء. اختر الرسم الصحيح «فئة / فؤة». اكتب جملة بمعنى واضح تحتوي كلمة «فئة».\n\nمفتاح الإجابة والتغذية الراجعة\n«بئر» لأن الكسرة قبل الهمزة أقوى من السكون؛ فئة؛ مثال «شاركت فئةٌ من الدارسين في النشاط».\n\nتطبيق من الحياة اليومية\nعندما تكتب تقريرًا عن مجموعة من الناس استخدم «فئة» كتابة صحيحة وراجع الحركة المحيطة بالهمزة.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يراجع قاعدة الهمزة المكسورة في ثلاثة سياقات.","يصحح أخطاء شائعة في «بئر» و«فئة».","يوظف كلمات بهمزة على نبرة في جمل من إنشائه."],"vocabulary":[{"word":"النبرة","meaning":"شكل الياء الذي تحمل عليه الهمزة"},{"word":"أقوى الحركتين","meaning":"الحركة الأرجح لرسم كرسي الهمزة"}],"quiz":{"prompt":"في أي كلمة كتبت الهمزة المتوسطة على نبرة كتابة صحيحة؟","options":["فئة","فؤة","فأة","فءة"],"correct":"فئة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":33,"title":"القواعد النحوية: الصفة والموصوف","content":"القواعد النحوية: الصفة والموصوف\n\nأهداف التعلّم\n• يعين النعت والمنعوت في جمل قصيرة.\n• يطابق النعت المنعوت في التعريف والتنكير والجنس.\n• يكتب وصفين مناسبين للأشخاص والأشياء.\n\nالشرح التعليمي الأصلي\nالصفة أو النعت تتبع الاسم الموصوف «المنعوت» في الإعراب، والتعريف والتنكير، والجنس، والعدد في النعت الحقيقي المناسب. «قرأت كتابًا مفيدًا»: «كتابًا» منعوت منصوب نكرة، و«مفيدًا» نعت منصوب نكرة. و«المكتبةُ الواسعةُ» صفة معرفة مؤنثة مرفوعة تتبع المكتبة. حين نكتب وصفًا لشخص نفضل صفة موضوعية تتعلق بسلوكه أو عمله، ولا نستخدم الوصف للإساءة إليه.\n\nأمثلة في السياق\n«رسالةٌ واضحةٌ» النعت «واضحةٌ». «الملفُّ المنظمُ» النعت «المنظمُ». يختلف الرسم حسب الاسم الموصوف.\n\nالتدريبات الفردية\nحدد النعت في «اشتريتُ قلمًا جديدًا». صحح «ذهبتُ إلى المدرسةِ الجديدُ». كوّن وصفًا مفيدًا للمركز بكلمتين.\n\nمفتاح الإجابة والتغذية الراجعة\nجديدًا؛ المدرسةِ الجديدةِ؛ مثل «المركزُ المنظمُ» أو «مركزٌ نظيفٌ» بحسب التركيب.\n\nتطبيق من الحياة اليومية\nعند وصف سلعة في إعلان بسيط، اختر صفتين واضحتين يمكن التحقق منهما دون مبالغة.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يعين النعت والمنعوت في جمل قصيرة.","يطابق النعت المنعوت في التعريف والتنكير والجنس.","يكتب وصفين مناسبين للأشخاص والأشياء."],"vocabulary":[{"word":"النعت","meaning":"اسم يبين صفة اسم قبله"},{"word":"المنعوت","meaning":"الاسم الذي تصفه الصفة"}],"quiz":{"prompt":"ما الصفة في «قرأتُ تقريرًا واضحًا»؟","options":["واضحًا","تقريرًا","قرأتُ","لا توجد"],"correct":"واضحًا"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":34,"title":"الإملاء: الهمزة المتوسطة المكسور ما قبلها","content":"الإملاء: الهمزة المتوسطة المكسور ما قبلها\n\nأهداف التعلّم\n• يميّز الكسرة السابقة للهمزة مهما تكن حركة الهمزة.\n• يعلل الرسم على نبرة في «فئة» و«بئر».\n• يصنف كلمتين بحسب حركة الهمزة.\n\nالشرح التعليمي الأصلي\nعندما يكون الحرف السابق للهمزة المتوسطة مكسورًا، فالكسرة أقوى من الضمة والفتحة والسكون، وغالبًا نرسم الهمزة على نبرة «ئ». في «فِئَة» الهمزة مفتوحة بعد كسرة، وفي «بِئْر» الهمزة ساكنة بعد كسرة. أما «مِئَة» فرسمها على ياء أيضًا. نحتاج في الإملاء إلى الاستماع للحركات والكتابة من المعنى، لا إلى تغيير الكلمة لتوافق شكلًا مألوفًا فقط.\n\nأمثلة في السياق\n«فئة» الهمزة مفتوحة بعد كسر الفاء. «بئر» الهمزة ساكنة بعد كسر الباء. كلاهما على نبرة.\n\nالتدريبات الفردية\nضع الهمزة في «فـ_ة» و«بـ_ر». اذكر حركة الهمزة في كل كلمة. اكتب جملة تتضمن «مئة» بعد التأكد من سياقها.\n\nمفتاح الإجابة والتغذية الراجعة\nفئة وبئر؛ همزة فئة مفتوحة، وهمزة بئر ساكنة؛ مثال «قرأت مئة كلمة» مع مراعاة ضوابط العدد في الصياغة.\n\nتطبيق من الحياة اليومية\nراجع كلمة «فئة» عند كتابة وصف لمجموعات المتعلمين، وتجنب تعميم الأحكام على الناس.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميّز الكسرة السابقة للهمزة مهما تكن حركة الهمزة.","يعلل الرسم على نبرة في «فئة» و«بئر».","يصنف كلمتين بحسب حركة الهمزة."],"vocabulary":[{"word":"الحركة السابقة","meaning":"الحركة على الحرف الذي قبل الهمزة"},{"word":"نبرة","meaning":"كرسي الهمزة الشبيه بالياء"}],"quiz":{"prompt":"ما سبب رسم الهمزة على نبرة في «فِئَة»؟","options":["لأن ما قبلها مكسور","لأنها في أول الكلمة","لأن قبلها ضمة فقط","لأنها همزة متطرفة"],"correct":"لأن ما قبلها مكسور"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":35,"title":"القراءة: على شواطئ البحرين - دراسة القصيدة كاملة، والحفظ من 1 إلى 5","content":"القراءة: على شواطئ البحرين - دراسة القصيدة كاملة، والحفظ من 1 إلى 5\n\nأهداف التعلّم\n• يقرأ وصفًا أصليًا لسلوك مسؤول على الشاطئ.\n• يستخرج صورتين مرتبطتين بالبحر.\n• يميز التدريب الأصلي من الأبيات الرسمية المطلوبة للحفظ.\n\nالشرح التعليمي الأصلي\nالعنوان الوارد بالخطة هو «على شواطئ البحرين» ومطلوب دراسة القصيدة كاملة وحفظ الأبيات 1–5. هذه المسودة لا تنقل القصيدة التي لم تُطابق بمصدر الكتاب. بديلها التدريبي المؤقت نص من ضاديوم: «جلس ماجد على الشاطئ وقت الغروب يراقب الموج. سمع صوت الماء ورأى أسرًا تجمع أدواتها قبل المغادرة. التقط ماجد عبوة بلاستيكية آمنة ووضعها في سلة النفايات. أدرك أن البحر مكان للجمال والعمل والمسؤولية». هذا مشهد نثري أصلي، لا أبيات شعرية مقررة.\n\nأمثلة في السياق\nصورتان: حركة الموج وقت الغروب، وصوت الماء. الفكرة: المحافظة على المكان بعد زيارته.\n\nالتدريبات الفردية\nمتى كان ماجد على الشاطئ؟ ما الفعل الذي يدل على مسؤوليته؟ صف صوتًا أو منظرًا بحريًا في جملتين. لا تحفظ هذه الفقرة على أنها جزء من القصيدة الرسمية.\n\nمفتاح الإجابة والتغذية الراجعة\nوقت الغروب؛ وضع العبوة في سلة النفايات؛ يقبل وصف غير منسوخ يوضح المنظر أو الصوت.\n\nتطبيق من الحياة اليومية\nاكتب تنبيهًا قصيرًا لزوار الشاطئ عن جمع المخلفات الآمنة وعدم الاقتراب من أجسام مجهولة أو حادة.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يقرأ وصفًا أصليًا لسلوك مسؤول على الشاطئ.","يستخرج صورتين مرتبطتين بالبحر.","يميز التدريب الأصلي من الأبيات الرسمية المطلوبة للحفظ."],"vocabulary":[{"word":"شاطئ","meaning":"منطقة اليابسة المحاذية للبحر"},{"word":"موج","meaning":"حركة سطح الماء صعودًا وهبوطًا"}],"quiz":{"prompt":"هل النص التدريبي هنا هو قصيدة الكتاب الرسمية؟","options":["لا، هو نص نثري أصلي داعم","نعم هو الأبيات الخمسة","نعم هو فهرس الكتاب","نعم مراجَع رسميًا"],"correct":"لا، هو نص نثري أصلي داعم"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":36,"title":"القواعد النحوية: النفي بـ(ما، لم، لن، لا، ليس)","content":"القواعد النحوية: النفي بـ(ما، لم، لن، لا، ليس)\n\nأهداف التعلّم\n• يميّز أدوات النفي الخمس بحسب الجملة.\n• يضبط المضارع الصحيح بعد «لم» و«لن».\n• يصوغ نفيًا واضحًا لموقف في الماضي أو المستقبل.\n\nالشرح التعليمي الأصلي\nالنفي ينكر وقوع الحدث أو ثبوت الصفة. «ما حضرتُ أمس» لنفي حدث ماضٍ في سياق مناسب؛ «لم أحضرْ أمس» فيها «لم» تجزم المضارع وتحوّل معناه إلى الماضي. «لن أتأخرَ غدًا» تنصب المضارع وتنفي المستقبل. «لا أهملُ العمل» نفي عادة مع مضارع مرفوع، بينما «لا تهملْ» نهي يجزم المضارع. «ليس الموعدُ بعيدًا» فعل ناسخ ينفي الجملة الاسمية، ويرفع اسمه وينصب خبره.\n\nأمثلة في السياق\nلم أسافرْ أمس؛ لن أسافرَ غدًا؛ ليس المكانُ بعيدًا؛ لا أنسى الموعدَ. نراقب المعنى والزمن والإعراب.\n\nالتدريبات الفردية\nاختر بين لم ولن: «___ أخرجْ أمس». اضبط «لن أترك ... الدراسة». صحح «ليس الطريقَ طويلٌ».\n\nمفتاح الإجابة والتغذية الراجعة\n«لم أخرجْ أمس»؛ «لن أتركَ الدراسة»؛ «ليس الطريقُ طويلًا».\n\nتطبيق من الحياة اليومية\nاكتب اعتذارًا مختصرًا ينفي تأخرك في موعد سابق، ووعدًا للمستقبل مستخدمًا «لن».\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميّز أدوات النفي الخمس بحسب الجملة.","يضبط المضارع الصحيح بعد «لم» و«لن».","يصوغ نفيًا واضحًا لموقف في الماضي أو المستقبل."],"vocabulary":[{"word":"نفي","meaning":"إنكار وقوع الفعل أو ثبوت الصفة"},{"word":"نهي","meaning":"طلب التوقف عن فعل"}],"quiz":{"prompt":"أي جملة تنفي فعلًا مستقبليًا؟","options":["لن أتأخرَ غدًا","لم أتأخرْ أمس","حضرتُ اليوم","اكتبْ الآن"],"correct":"لن أتأخرَ غدًا"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":37,"title":"القراءة: الكلب والحمامة - دراسة القصيدة كاملة، والحفظ من 1 إلى 5","content":"القراءة: الكلب والحمامة - دراسة القصيدة كاملة، والحفظ من 1 إلى 5\n\nأهداف التعلّم\n• يستنتج قيمة المساعدة من حكاية أصلية مستقلة.\n• يرتب أحداث الحكاية من البداية للنهاية.\n• يفرق بين قصة تدريبية والقصيدة الرسمية التي تنتظر التحقق.\n\nالشرح التعليمي الأصلي\nتورد الخطة قصيدة «الكلب والحمامة» لدراستها كاملة وحفظ الأبيات 1–5. لا نعرض هنا أبياتًا غير موثقة أو نزعم أنها الأصل. الحكاية الآتية من تأليف ضاديوم للتدرب على الفهم: «رأت حمامة كلبًا عطشان قرب حديقة. انتبه صاحب الحديقة إلى الكلب فوضع له وعاء ماء نظيفًا بعيدًا عن الطريق. ارتاحت الحمامة فوق الشجرة، وشكر صاحب الحديقة زواره على مساعدتهم». لا تؤنسن الحيوانات على أنها تتكلم بالفعل؛ المطلوب استنتاج قيمة الرفق وتحديد دور الإنسان المسؤول.\n\nأمثلة في السياق\nبداية: كلب عطشان. استجابة: صاحب الحديقة وفر الماء. نتيجة: زالت المشكلة بطريقة آمنة. قيمة: الرحمة بالحيوان.\n\nالتدريبات الفردية\nمن الذي وضع الماء؟ ماذا كانت مشكلة الكلب؟ اكتب حكاية من أربع جمل عن مساعدة مخلوق دون الاقتراب من حيوان مجهول. انتظر الكتاب للتحقق من النص الشعري المطلوب حفظه.\n\nمفتاح الإجابة والتغذية الراجعة\nصاحب الحديقة؛ العطش؛ تقبل حكاية لها مشكلة وحل ونتيجة مع مراعاة السلامة.\n\nتطبيق من الحياة اليومية\nإذا لاحظت حيوانًا يحتاج مساعدة، أخبر المسؤول أو الجهة المختصة بدل ملامسته إن كان مجهولًا أو عدوانيًا.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يستنتج قيمة المساعدة من حكاية أصلية مستقلة.","يرتب أحداث الحكاية من البداية للنهاية.","يفرق بين قصة تدريبية والقصيدة الرسمية التي تنتظر التحقق."],"vocabulary":[{"word":"الرفق","meaning":"التعامل بلطف ورحمة"},{"word":"تسلسل","meaning":"ترتيب الأحداث بحسب وقوعها"}],"quiz":{"prompt":"من الذي قدّم الماء للكلب في حكاية ضاديوم؟","options":["صاحب الحديقة","الحمامة","الكلب الآخر","سائق الحافلة"],"correct":"صاحب الحديقة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":38,"title":"الإملاء: الهمزة المتطرفة المكسور ما قبلها","content":"الإملاء: الهمزة المتطرفة المكسور ما قبلها\n\nأهداف التعلّم\n• يتعرف الهمزة المتطرفة في نهاية الكلمات.\n• يرسم الهمزة على ياء عندما يسبقها كسر.\n• يكتب «شاطئ» و«قارئ» و«هادئ» بصورة صحيحة.\n\nالشرح التعليمي الأصلي\nالهمزة المتطرفة تقع في آخر الكلمة، ويعتمد كرسيها على حركة الحرف الذي قبلها، لا على حركة الهمزة نفسها. إذا كان السابق مكسورًا كتبت الهمزة على ياء «ئ»: «شاطِئ»، «قارِئ»، «هادِئ». إذا كان السابق مضمومًا قد تكون على واو مثل «تباطُؤ»، وإذا كان مفتوحًا على ألف مثل «ملجَأ». نحدد الحركة السابقة قبل كتابة الكلمة.\n\nأمثلة في السياق\n«القارئُ هادئٌ» فيها كلمتان آخرهما همزة على ياء: قارئ، هادئ. «على شاطئ البحر» كذلك.\n\nالتدريبات الفردية\nأكمل «قار_» و«هاد_» و«شاط_». ما حركة الحرف قبل الهمزة؟ اكتب جملة تحتوي كلمتين من الثلاث.\n\nمفتاح الإجابة والتغذية الراجعة\nقارئ، هادئ، شاطئ؛ الحركة الكسرة؛ مثال «جلس قارئٌ هادئٌ قرب الشاطئ».\n\nتطبيق من الحياة اليومية\nراجع رسم «شاطئ» عند كتابة إعلان لنشاط بيئي، ولا تكتبها بهمزة منفصلة عن كرسيها.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يتعرف الهمزة المتطرفة في نهاية الكلمات.","يرسم الهمزة على ياء عندما يسبقها كسر.","يكتب «شاطئ» و«قارئ» و«هادئ» بصورة صحيحة."],"vocabulary":[{"word":"متطرفة","meaning":"همزة في نهاية الكلمة"},{"word":"كرسي الياء","meaning":"شكل يحمل الهمزة عندما يناسب الكسرة"}],"quiz":{"prompt":"أي رسم صحيح لكلمة تدل على قارئ الكتب؟","options":["قارئ","قارء","قارؤ","قارأ"],"correct":"قارئ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":39,"title":"الإنتاج الكتابي: بطاقة الدعوة (1) و(2)","content":"الإنتاج الكتابي: بطاقة الدعوة (1) و(2)\n\nأهداف التعلّم\n• يحدد الغرض والمكان والموعد في بطاقة دعوة.\n• يختار تحية مناسبة للمدعو.\n• ينشئ بطاقة مختصرة لا تتضمن معلومات غير مؤكدة.\n\nالشرح التعليمي الأصلي\nبطاقة الدعوة نص قصير يطلب حضور شخص إلى مناسبة أو نشاط. يجب أن يظهر فيها نوع المناسبة، واسم الجهة أو صاحب الدعوة، والموعد، والمكان، ووسيلة للاستفسار عند الحاجة. مثال تدريبي: «يسرّ مركز التعلم دعوتكم إلى لقاء القراءة يوم الخميس الساعة الخامسة مساءً في القاعة العامة. الرجاء تأكيد الحضور». هذه بيانات افتراضية ينبغي استبدالها بالبيانات الحقيقية قبل الاستخدام؛ لا ندّعي إقامة حدث فعلي.\n\nأمثلة في السياق\nالجهة الداعية: المركز. المناسبة: لقاء القراءة. المكان: القاعة العامة. اليوم والساعة محددان بوضوح في المثال الافتراضي.\n\nالتدريبات الفردية\nاستخرج موعد اللقاء من المثال. ما المعلومات الناقصة إذا كتبت «يسرنا حضوركم» وحدها؟ صمم بطاقة من خمسة أسطر لنشاط تخيلي مع توضيح أنه مثال تعليمي.\n\nمفتاح الإجابة والتغذية الراجعة\nالموعد الخميس الخامسة مساءً؛ تنقص المناسبة والمكان والتوقيت والجهة؛ تقبل بطاقة دقيقة التنظيم لا تدّعي إعلانًا حقيقيًا.\n\nتطبيق من الحياة اليومية\nعند تلقي دعوة حقيقية راجع التاريخ والمكان واسم الجهة من مصدر موثوق قبل مشاركتها.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد الغرض والمكان والموعد في بطاقة دعوة.","يختار تحية مناسبة للمدعو.","ينشئ بطاقة مختصرة لا تتضمن معلومات غير مؤكدة."],"vocabulary":[{"word":"مدعو","meaning":"الشخص المطلوب حضوره"},{"word":"تأكيد الحضور","meaning":"إبلاغ الجهة بالموافقة على المشاركة"}],"quiz":{"prompt":"أي معلومة ضرورية في بطاقة الدعوة؟","options":["موعد المناسبة ومكانها","خاتمة قصة طويلة","رقم لا علاقة له بالمناسبة","اسم غير صحيح"],"correct":"موعد المناسبة ومكانها"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":40,"title":"القواعد النحوية: العطف بـ(الواو، ثم، أو)","content":"القواعد النحوية: العطف بـ(الواو، ثم، أو)\n\nأهداف التعلّم\n• يميز دلالة الواو وثم وأو في سياقات متنوعة.\n• يحدد المعطوف والمعطوف عليه.\n• يكتب ثلاث جمل تربط أحداثًا واختيارات.\n\nالشرح التعليمي الأصلي\nالعطف يربط بين كلمات أو جمل بحرف مناسب. «زار سالمٌ المكتبةَ والمركزَ» الواو تفيد المشاركة ولا يلزم منها ترتيب زمني. «قرأتُ التعليماتِ ثم وقّعتُ» تفيد ثم الترتيب مع تراخٍ مناسب للسياق. «اشرب ماءً أو عصيرًا» تعرض اختيارًا بين أمرين. المعطوف يتبع المعطوف عليه في الإعراب في عطف المفردات، فلا نهمل الحركة عند التدريب.\n\nأمثلة في السياق\n«سالمٌ وأحمدُ» مشاركة. «أنهيتُ التمرين ثم راجعته» ترتيب. «دفترٌ أو ورقةٌ» اختيار.\n\nالتدريبات الفردية\nاختر الحرف المناسب «راجعتُ البيانات ___ أرسلتُ الطلب» عندما تريد الترتيب. صنف جملة «الشاي أو القهوة». كوّن جملة بالواو دون قصد الترتيب.\n\nمفتاح الإجابة والتغذية الراجعة\nثم؛ اختيار؛ مثال «حضر خالدٌ وسالمٌ اللقاءَ» والواو لا تثبت ترتيب الحضور.\n\nتطبيق من الحياة اليومية\nاكتب تعليمات من خطوتين باستخدام «ثم»، وقائمة اختيار من بديلين باستخدام «أو».\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز دلالة الواو وثم وأو في سياقات متنوعة.","يحدد المعطوف والمعطوف عليه.","يكتب ثلاث جمل تربط أحداثًا واختيارات."],"vocabulary":[{"word":"المعطوف","meaning":"اسم أو جملة يربطها حرف عطف بما قبلها"},{"word":"تراخٍ","meaning":"وجود مهلة أو فاصل بين حدثين"}],"quiz":{"prompt":"أي حرف أنسب لبيان ترتيب حدثين مع مهلة؟","options":["ثم","أو","الواو دون قرينة","هل"],"correct":"ثم"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":41,"title":"الإنتاج الكتابي: بطاقة الدعوة (3)","content":"الإنتاج الكتابي: بطاقة الدعوة (3)\n\nأهداف التعلّم\n• يراجع بطاقة دعوة ويصحح نقصًا فيها.\n• يميز الإعلان المؤكد من الدعوة التدريبية.\n• يكتب نسخة نهائية موجزة بعد مراجعة الوقت والعنوان.\n\nالشرح التعليمي الأصلي\nبعد إعداد بطاقة الدعوة نراجع صحتها ووضوحها قبل إرسالها. نتحقق من اسم النشاط، والجهة الداعية، والتاريخ باليوم والسنة عند الحاجة، والوقت والمنطقة الزمنية إن كان اللقاء عن بعد، والمكان أو الرابط الرسمي. مثال غير مكتمل «لقاء الخميس في المركز» قد يربك القارئ؛ ننقحه بإضافة عنوان القاعة والساعة والجهة. نحذف روابط غير موثقة وبيانات حساسة، ولا نستخدم صيغة تأكيد حدث غير معتمد.\n\nأمثلة في السياق\nبطاقة ناقصة: «ندعوكم إلى اللقاء». البطاقة المحسنة: «يدعوكم نادي القراءة إلى جلسة تدريبية افتراضية يوم الخميس الساعة الخامسة مساءً وفق توقيت البحرين»، مع إضافة الرابط المعتمد عند توفره.\n\nالتدريبات الفردية\nاكتب ثلاثة أوجه نقص في البطاقة الأولى. راجع بطاقة أنتجتها في الدرس السابق. تحقق من ترتيب المعلومات وصحة الكلمات التي تحتوي همزات.\n\nمفتاح الإجابة والتغذية الراجعة\nتنقص المناسبة والموعد والمكان أو الرابط والجهة الداعية؛ تقبل بطاقة نهائية مستوفية لهذه البنود مع توضيح أن بيانات المثال افتراضية.\n\nتطبيق من الحياة اليومية\nراجع دعوة حقيقية في هاتفك قبل إعادة توجيهها، خاصة اسم الجهة والتوقيت والرابط.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يراجع بطاقة دعوة ويصحح نقصًا فيها.","يميز الإعلان المؤكد من الدعوة التدريبية.","يكتب نسخة نهائية موجزة بعد مراجعة الوقت والعنوان."],"vocabulary":[{"word":"تنقيح","meaning":"تحسين النص بعد المراجعة"},{"word":"رابط معتمد","meaning":"رابط ثبتت صحته من الجهة الداعية"}],"quiz":{"prompt":"ما الذي يجب فعله قبل إرسال دعوة تحتوي رابط حضور؟","options":["التحقق من الرابط لدى الجهة المنظمة","نسخ أي رابط مجهول","حذف وقت اللقاء","إخفاء اسم الجهة"],"correct":"التحقق من الرابط لدى الجهة المنظمة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":42,"title":"الإملاء: الهمزة المتطرفة المسبوقة بحرف ساكن صحيح أو حرف علة","content":"الإملاء: الهمزة المتطرفة المسبوقة بحرف ساكن صحيح أو حرف علة\n\nأهداف التعلّم\n• يميز الساكن الصحيح من حرف المد قبل الهمزة المتطرفة.\n• يرسم الهمزة على السطر في «جزء» و«شيء».\n• يقارن مع همزة آخر «قارئ» بعد كسرة.\n\nالشرح التعليمي الأصلي\nتكتب الهمزة المتطرفة على السطر إذا سبقها حرف ساكن لا حركة له، مثل «جُزْء» حيث الزاي ساكنة، أو سبقها حرف مد مثل «ماء» و«هدوء» و«شيء» التي فيها الياء ساكنة. أما «قارئ» فالراء مكسورة، ولذلك كتبت الهمزة على ياء. لا نضيف كرسِيًا للهمزة المتطرفة بعد ساكن لمجرد أنها تأتي بعد حرف في الرسم، بل نفحص حركة ما قبلها بدقة.\n\nأمثلة في السياق\n«جزء» الهمزة على السطر بعد زاي ساكنة. «ماء» على السطر بعد ألف مد. «قارئ» على ياء بعد راء مكسورة.\n\nالتدريبات الفردية\nاكمل «جز_» و«ما_» و«قار_». لماذا اختلف كرسي الهمزة الأخيرة في «قارئ»؟ اكتب جملة بكلمة «شيء» من حياتك.\n\nمفتاح الإجابة والتغذية الراجعة\nجزء، ماء، قارئ؛ لأن ما قبل همزة قارئ مكسور، أما جزء وماء فقبلهما ساكن أو مد.\n\nتطبيق من الحياة اليومية\nفي ملاحظات العمل، اكتب «جزء» و«شيء» بوضوح، وراجع آخر الكلمة قبل الإرسال.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز الساكن الصحيح من حرف المد قبل الهمزة المتطرفة.","يرسم الهمزة على السطر في «جزء» و«شيء».","يقارن مع همزة آخر «قارئ» بعد كسرة."],"vocabulary":[{"word":"ساكن صحيح","meaning":"حرف صحيح لا حركة قصيرة عليه"},{"word":"حرف مد","meaning":"ألف أو واو أو ياء تمد الصوت وفق شرطها"}],"quiz":{"prompt":"أي كلمة كتبت همزتها المتطرفة على السطر بعد ساكن؟","options":["جزء","قارئ","ملجأ","لؤلؤ"],"correct":"جزء"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":43,"title":"مراجعة عامة","content":"مراجعة عامة\n\nأهداف التعلّم\n• يربط بين نحو الجملة والإملاء والقراءة الوظيفية.\n• يصحح نصًا قصيرًا متعدد الأخطاء.\n• ينتج رسالة أو تقريرًا منظمًا مستعينًا بما تعلمه.\n\nالشرح التعليمي الأصلي\nهذه مراجعة تجمع أهم المهارات التي تدرب عليها الدارس في المستوى: تحديد الفاعل والمفعول به، وضبط المبتدأ والخبر، والتمييز بين «كان» و«إن»، واختيار حرف الجر، ورسم الهمزة، وكتابة الرسالة والتقرير والدعوة. في نص تدريبي: «قرأَ الموظفُ الرسالةَ، ثم كتب تقريرًا واضحًا. إنَّ العملَ منظّمٌ عندما تكون البيانات دقيقة». نحدد فعلًا وفاعلًا ومفعولًا، ونلاحظ العطف بـ«ثم»، ونراجع اسم إن وخبرها دون تعميم أحكام خاطئة.\n\nأمثلة في السياق\nفي «قرأ الموظف الرسالة» الفاعل الموظفُ والمفعول الرسالةَ. «إن العمل منظّم» عملَ اسم إن ومنظمٌ خبرها. «ثم» يدل على الترتيب.\n\nالتدريبات الفردية\nحلّل جملة «أرسلَ الدارسُ رسالةً قصيرةً». اختر الشكل الصحيح «قارئ/قارء». اكتب بطاقة دعوة افتراضية من أربعة أسطر ثم راجع بياناتها ولغتها.\n\nمفتاح الإجابة والتغذية الراجعة\nالفاعل الدارسُ؛ المفعول رسالةً والنعت قصيرةً؛ «قارئ»؛ تقبل بطاقة تبين الغرض والجهة والزمان والمكان.\n\nتطبيق من الحياة اليومية\nحدّد مهارتين تحتاج إلى ممارسة إضافية وضع خطة قصيرة للأسبوع القادم، مع الاستعانة بمعلمك في مراجعة الكتاب الرسمي.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يربط بين نحو الجملة والإملاء والقراءة الوظيفية.","يصحح نصًا قصيرًا متعدد الأخطاء.","ينتج رسالة أو تقريرًا منظمًا مستعينًا بما تعلمه."],"vocabulary":[{"word":"مراجعة تراكمية","meaning":"تدريب يجمع عدة مهارات"},{"word":"تقويم ذاتي","meaning":"تحديد ما أتقنته وما أحتاج تحسينه"}],"quiz":{"prompt":"ما الفاعل في «قرأَ الموظفُ الرسالةَ»؟","options":["الموظفُ","الرسالةَ","قرأَ","لا يوجد"],"correct":"الموظفُ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false}]$PAYLOAD$::jsonb)),
target AS (
 SELECT l.id,p.j FROM payload p
 JOIN public.lessons l ON l.title=p.j->>'title'
 JOIN public.units u ON u.id=l.unit_id AND u.semester=1
 JOIN public.grades g ON g.id=u.grade_id AND g.name_ar='الأول متابعة' AND g.grade_number IS NULL
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries co ON co.id=cu.country_id AND co.code='BH'
 WHERE l.content='محتوى مقرر في الخطة الرسمية الحالية. يُحفظ العنوان كما في المصدر بعد تنظيف أخطاء OCR الشكلية فقط.'
 AND l.learning_objectives='[]'::jsonb AND l.instructions='[]'::jsonb
)
UPDATE public.lessons l SET
 content=t.j->>'content',learning_objectives=t.j->'learning_objectives',
 vocabulary=t.j->'vocabulary',updated_at=now(),
 instructions=jsonb_build_array(jsonb_build_object('origin','DADYOOM_BH_FOLLOWUP1_DRAFT_V1','editorial_review','required','book_text_copied',false))
FROM target t WHERE l.id=t.id;

WITH payload AS (SELECT value AS j FROM jsonb_array_elements($PAYLOAD$[{"order":26,"title":"القراءة: نزهة في أحضان الطبيعة","content":"القراءة: نزهة في أحضان الطبيعة\n\nأهداف التعلّم\n• يقرأ نصًا وصفيًا أصليًا ويستخرج تفاصيل المكان.\n• يميّز فعلًا يدل على مسؤولية الزائر.\n• يكتب انطباعًا قصيرًا عن بيئة طبيعية.\n\nالشرح التعليمي الأصلي\nنقرأ مشهدًا أصليًا لا يطابق نص الكتاب: «خرجت هدى مع أسرتها إلى حديقة عامة صباحًا. لاحظت الأشجار والطيور ومسار المشي. بعد تناول الطعام جمعت الأسرة مخلفاتها في كيس مخصص، وتركت المكان نظيفًا ليستمتع به زوار آخرون. قالت هدى: جمال الطبيعة يحتاج منا إلى عناية لا إلى مديح فقط». تتسلسل الأحداث من الزيارة إلى المحافظة على المكان، ونستنتج أن احترام البيئة مسؤولية مشتركة.\n\nأمثلة في السياق\nتفصيل حسي: صوت الطيور. سلوك عملي: جمع المخلفات. فكرة النص: الاستمتاع بالطبيعة لا ينفصل عن حمايتها.\n\nالتدريبات الفردية\nمتى خرجت الأسرة؟ اذكر عنصرين طبيعيين في الحديقة. ما الدليل على احترام الزوار الآخرين؟ اكتب أربعة أسطر تصف زيارة مشابهة دون نقل النص حرفيًا.\n\nمفتاح الإجابة والتغذية الراجعة\nصباحًا؛ الأشجار والطيور؛ ترك المكان نظيفًا؛ تقبل أوصاف شخصية مترابطة تُظهر المكان والفعل والشعور.\n\nتطبيق من الحياة اليومية\nدوّن قاعدة واحدة تساعدك عند زيارة حديقة أو ساحل، وطبّقها فعلًا في الرحلة المقبلة.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يقرأ نصًا وصفيًا أصليًا ويستخرج تفاصيل المكان.","يميّز فعلًا يدل على مسؤولية الزائر.","يكتب انطباعًا قصيرًا عن بيئة طبيعية."],"vocabulary":[{"word":"مسار","meaning":"طريق محدد للمشي"},{"word":"مخلفات","meaning":"أشياء تُترك بعد الاستخدام"}],"quiz":{"prompt":"كيف حافظت الأسرة على الحديقة؟","options":["جمعت مخلفاتها","تركت العبوات","قطفت الأشجار","أزعجت الزوار"],"correct":"جمعت مخلفاتها"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":27,"title":"القواعد النحوية: الأسماء المجرورة بحروف الجر","content":"القواعد النحوية: الأسماء المجرورة بحروف الجر\n\nأهداف التعلّم\n• يتعرف حروف الجر الأساسية في جمل ذات معنى.\n• يحدد الاسم المجرور وحركته في مثال مفرد.\n• يصوغ عبارتين صحيحتين عن المكان والاتجاه.\n\nالشرح التعليمي الأصلي\nتدخل حروف الجر على الأسماء فتجعلها مجرورة: من، إلى، عن، على، في، الباء، اللام والكاف في مواضعها. في «ذهبتُ إلى المكتبةِ» الاسم «المكتبةِ» مجرور بـ«إلى» وعلامة جره الكسرة؛ وفي «جلستُ على المقعدِ» المقعدِ اسم مجرور. وقد تكون علامة الجر الياء في المثنى أو جمع المذكر السالم مثل «مررتُ بالمعلمينَ». نميز الحرف عن الاسم الذي يليه ولا نغير رسم الحرف نفسه.\n\nأمثلة في السياق\n«في القاعةِ» جار ومجرور. «من المنزلِ إلى السوقِ» حرفا جر ويتبعهما اسمان مجروران.\n\nالتدريبات الفردية\nحدد الاسم المجرور في «وضعت الملفَّ في الحقيبةِ». اضبط «على المكتب» ضبطًا صحيحًا. كوّن جملة تستخدم فيها «من» للابتداء.\n\nمفتاح الإجابة والتغذية الراجعة\nالحقيبةِ؛ على المكتبِ؛ مثال «سرت من المنزلِ إلى المركزِ».\n\nتطبيق من الحياة اليومية\nاكتب تعليمات مسار إلى غرفة الاستقبال باستخدام «إلى» و«في»، ثم ضع كسرة المجرور المفرد.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يتعرف حروف الجر الأساسية في جمل ذات معنى.","يحدد الاسم المجرور وحركته في مثال مفرد.","يصوغ عبارتين صحيحتين عن المكان والاتجاه."],"vocabulary":[{"word":"حرف جر","meaning":"حرف يجر الاسم بعده"},{"word":"الكسرة","meaning":"علامة الجر الأصلية للاسم المفرد"}],"quiz":{"prompt":"ما الاسم المجرور في «أضعُ الكتابَ على الرفِّ»؟","options":["الرفِّ","الكتابَ","أضعُ","على"],"correct":"الرفِّ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":28,"title":"الإملاء: الهمزة المتوسطة المكسورة (1)","content":"الإملاء: الهمزة المتوسطة المكسورة (1)\n\nأهداف التعلّم\n• يميز الهمزة المتوسطة المكسورة عن المفتوحة.\n• يستنتج أن الكسرة أقوى الحركات عند رسم الهمزة.\n• يكتب كلمات «سُئِل» و«رَئِيس» كتابة سليمة.\n\nالشرح التعليمي الأصلي\nمن أسس كتابة الهمزة المتوسطة مقارنة حركة الهمزة بحركة الحرف السابق. الكسرة أقوى من الضمة والفتحة والسكون، ويناسبها كرسي الياء (ئ). في «سُئِلَ» الهمزة مكسورة وما قبلها مضموم، فتكتب على ياء. وفي «رَئِيس» الهمزة مكسورة وما قبلها مفتوح، فتكتب على ياء أيضًا. ننتبه إلى شكل الكلمة قبل التسرع في الرسم، ولا نضيف نقطتين مستقلتين إلى كرسي الهمزة.\n\nأمثلة في السياق\n«سُئِلَ الرجلُ عن الموعد» و«رَئِيس القسمِ حاضرٌ» تشتملان همزة متوسطة مكسورة مرسومة على ياء.\n\nالتدريبات الفردية\nحدد حركة الهمزة في «رئيس». اختر رسم «سُئِل / سُؤِل» في البناء للمجهول. اكتب جملة تستخدم فيها «رئيس» مع الضبط إن استطعت.\n\nمفتاح الإجابة والتغذية الراجعة\nالهمزة مكسورة؛ «سُئِلَ»؛ مثال «رئيسُ الفريقِ حاضرٌ».\n\nتطبيق من الحياة اليومية\nإذا وردت كلمة «رئيس» في رسالة رسمية، راجع موضع الهمزة على ياء قبل إرسالها.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز الهمزة المتوسطة المكسورة عن المفتوحة.","يستنتج أن الكسرة أقوى الحركات عند رسم الهمزة.","يكتب كلمات «سُئِل» و«رَئِيس» كتابة سليمة."],"vocabulary":[{"word":"كسرة","meaning":"حركة قصيرة أقوى الحركات في رسم الهمزة"},{"word":"نبرة الهمزة","meaning":"كرسي الياء الذي يحمل الهمزة"}],"quiz":{"prompt":"لماذا رُسمت همزة «سُئِلَ» على ياء؟","options":["لأن الهمزة مكسورة","لأنها في آخر الكلمة","لأنها ساكنة بعد ألف","لأن الكلمة لا حركة فيها"],"correct":"لأن الهمزة مكسورة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":29,"title":"الإنتاج الكتابي: المذكرات اليومية (3)","content":"الإنتاج الكتابي: المذكرات اليومية (3)\n\nأهداف التعلّم\n• يحرر مذكرة فيها حدث وشعور وتأمل شخصي.\n• يراجع التسلسل الزمني للأحداث.\n• يحذف تفصيلًا خاصًا غير ضروري من مذكرة يشاركها.\n\nالشرح التعليمي الأصلي\nفي تطوير المذكرات اليومية ننتقل من ذكر الحدث إلى فهم أثره والتخطيط للمستقبل. مثال أصلي: «الثلاثاء: وصلت إلى مركز التعلم مبكرًا. قرأت الإعلان على الباب دون مساعدة للمرة الأولى. شعرت بالثقة لأنني كنت أتدرب طوال الأسبوع. سأكرر قراءة اللوحات في الأماكن العامة». تتضمن المذكرة تاريخًا تقريبيًا وحدثًا يمكن وصفه وشعورًا وقرارًا. عند مشاركة المذكرة نحذف ما قد يمس خصوصية الزملاء.\n\nأمثلة في السياق\nحدث: قراءة الإعلان. أثر: زيادة الثقة. خطة: ممارسة القراءة في الحياة اليومية.\n\nالتدريبات الفردية\nرتب من المثال: الحدث، الشعور، القرار. اكتب مذكرة من خمس جمل عن تجربة تعلم، ثم احذف منها معلومة تخص شخصًا آخر دون إذنه.\n\nمفتاح الإجابة والتغذية الراجعة\nالحدث أولًا ثم الشعور ثم القرار؛ تقبل مذكرة شخصية ذات زمن واضح وتسلسل صحيح وتحترم خصوصية الآخرين.\n\nتطبيق من الحياة اليومية\nاكتب في نهاية كل أسبوع إنجازًا واحدًا وتحديًا واحدًا وخطوة للتعلم دون المبالغة في وصف نفسك.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحرر مذكرة فيها حدث وشعور وتأمل شخصي.","يراجع التسلسل الزمني للأحداث.","يحذف تفصيلًا خاصًا غير ضروري من مذكرة يشاركها."],"vocabulary":[{"word":"تأمل","meaning":"تفكير في معنى التجربة"},{"word":"خصوصية","meaning":"حق الشخص في حماية معلوماته"}],"quiz":{"prompt":"أي عنصر يطوّر المذكرة من سرد بسيط إلى تأمل؟","options":["ما تعلمه الكاتب من التجربة","رقم غير موثق","حذف التاريخ","تكرار الحدث وحده"],"correct":"ما تعلمه الكاتب من التجربة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":30,"title":"القراءة: بيئتنا حياتنا - دراسة القصيدة كاملة، والحفظ من 1 إلى 6","content":"القراءة: بيئتنا حياتنا - دراسة القصيدة كاملة، والحفظ من 1 إلى 6\n\nأهداف التعلّم\n• يفهم فكرة المسؤولية البيئية في نص أصلي مستقل.\n• يحدد سببًا ونتيجة في موقف عن النظافة.\n• يميز التمرين الأصلي من القصيدة الرسمية التي لم يُتحقق من متنها.\n\nالشرح التعليمي الأصلي\nخطة الدرس تتضمن قصيدة «بيئتنا حياتنا» ودراسة القصيدة كاملة وحفظ الأبيات 1–6. لا يتوفر لدينا فهرس ومتن موثقان هنا، ولذلك لا ننسب أبياتًا إلى الكتاب. نقدم بدلًا من ذلك نصًا داعمًا من تأليف ضاديوم: «رأى عادل ورقة على الأرض في ساحة مركز التعلم. وضعها في السلة، ثم اقترح على زملائه توزيع السلال قرب المداخل. لاحظ الجميع أن ترتيب المكان يجعل الحركة أكثر راحة ويحمي المنظر العام». نستخرج علاقة السبب والنتيجة ونستعد لاحقًا لدراسة القصيدة الأصلية عند التحقق منها.\n\nأمثلة في السياق\nسبب: وضع السلال في مواضع مناسبة. نتيجة متوقعة: سهولة التخلص من المخلفات. العبارة «بيئتنا حياتنا» تؤكد الصلة بين جودة البيئة وحياة الناس.\n\nالتدريبات الفردية\nاذكر المبادرة التي اقترحها عادل. استنتج نتيجة للالتزام بها. اكتب عبارة إرشادية من سطر واحد عن نظافة المكان. لا تبدأ بحفظ أبيات على أنها مقررة دون المصدر الرسمي.\n\nمفتاح الإجابة والتغذية الراجعة\nاقترح توزيع السلال قرب المداخل؛ تقليل المخلفات وتيسير التخلص منها؛ مثال «حافظ على نظافة المكان ليستفيد الجميع».\n\nتطبيق من الحياة اليومية\nشارك في مبادرة بسيطة لتنظيف مساحة عامة دون التعامل مع مواد حادة أو خطرة، واستعن بالمختصين إذا وجدت مخلفات مؤذية.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يفهم فكرة المسؤولية البيئية في نص أصلي مستقل.","يحدد سببًا ونتيجة في موقف عن النظافة.","يميز التمرين الأصلي من القصيدة الرسمية التي لم يُتحقق من متنها."],"vocabulary":[{"word":"مبادرة","meaning":"عمل إيجابي يبدأ باقتراح وتنفيذ"},{"word":"نتيجة","meaning":"أثر ينشأ عن سبب"}],"quiz":{"prompt":"ما حالة أبيات القصيدة المقررة في هذه المسودة؟","options":["لم تتم مطابقتها بمصدر رسمي بعد","حُفظت من الكتاب مباشرة","مراجعة نهائيًا","نُقلت حرفيًا هنا"],"correct":"لم تتم مطابقتها بمصدر رسمي بعد"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":31,"title":"القواعد النحوية: الأسماء المجرورة بالإضافة","content":"القواعد النحوية: الأسماء المجرورة بالإضافة\n\nأهداف التعلّم\n• يميز المضاف والمضاف إليه في أربع تراكيب.\n• يعرب مضافًا إليه مفردًا بالكسرة.\n• يفرق بين الإضافة والجار والمجرور.\n\nالشرح التعليمي الأصلي\nالإضافة تركيب بين اسمين يوضح علاقة أحدهما بالآخر، ويكون الاسم الثاني «مضافًا إليه» مجرورًا. في «كتابُ الطالبِ» كلمة «كتابُ» مضاف بحسب موقعها، و«الطالبِ» مضاف إليه مجرور بالكسرة. لا نضع حرف جر بين الاسمين في المثال. قد يكون المضاف منصوبًا أو مرفوعًا أو مجرورًا بحسب الجملة، لكن المضاف إليه مجرور دائمًا. «بابُ المركزِ مفتوحٌ» مثال مناسب من الحياة اليومية.\n\nأمثلة في السياق\n«عنوانُ الرسالةِ واضحٌ»: الرسالةِ مضاف إليه. «ذهبت إلى المركزِ» جار ومجرور وليس إضافة.\n\nالتدريبات الفردية\nحدد المضاف إليه في «نافذةُ الصفِّ مفتوحةٌ». كوّن تركيبًا بإضافة «المكتبِ» إلى «بابُ». ضع حركة الاسم الثاني في «وقتُ الدرس».\n\nمفتاح الإجابة والتغذية الراجعة\nالصفِّ؛ بابُ المكتبِ؛ وقتُ الدرسِ.\n\nتطبيق من الحياة اليومية\nاكتب ثلاثة تراكيب تساعدك على وصف مقتنيات المنزل أو المستندات: رقمُ الهاتفِ، موعدُ اللقاءِ، عنوانُ المركزِ.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز المضاف والمضاف إليه في أربع تراكيب.","يعرب مضافًا إليه مفردًا بالكسرة.","يفرق بين الإضافة والجار والمجرور."],"vocabulary":[{"word":"إضافة","meaning":"تركيب يربط اسمًا باسم"},{"word":"مضاف إليه","meaning":"اسم مجرور يأتي بعد المضاف"}],"quiz":{"prompt":"ما المضاف إليه في «موعدُ الدرسِ قريبٌ»؟","options":["الدرسِ","موعدُ","قريبٌ","لا يوجد"],"correct":"الدرسِ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":32,"title":"الإملاء: الهمزة المتوسطة المكسورة (2)","content":"الإملاء: الهمزة المتوسطة المكسورة (2)\n\nأهداف التعلّم\n• يراجع قاعدة الهمزة المكسورة في ثلاثة سياقات.\n• يصحح أخطاء شائعة في «بئر» و«فئة».\n• يوظف كلمات بهمزة على نبرة في جمل من إنشائه.\n\nالشرح التعليمي الأصلي\nفي التدريب الثاني نتعامل مع الهمزة المكسورة بعد السكون أو الفتحة، مع النظر دائمًا إلى أقوى الحركتين. نقول «بِئْر» حيث همزتها ساكنة وما قبلها مكسور، فترسم على ياء لقوة الكسرة، بينما في «فِئَة» الهمزة مفتوحة وما قبلها مكسور فترسم كذلك على ياء. وفي «سُئِلَ» الهمزة مكسورة بعد ضمة. هذه ثلاث حالات مختلفة تصل كلها إلى الكرسي نفسه، فلا يكفي حفظ شكل الكلمة من غير تفسير.\n\nأمثلة في السياق\nبئر: ما قبل الهمزة مكسور. فئة: ما قبل الهمزة مكسور. سئل: الهمزة مكسورة.\n\nالتدريبات الفردية\nاشرح سبب رسم همزة «بئر» على ياء. اختر الرسم الصحيح «فئة / فؤة». اكتب جملة بمعنى واضح تحتوي كلمة «فئة».\n\nمفتاح الإجابة والتغذية الراجعة\n«بئر» لأن الكسرة قبل الهمزة أقوى من السكون؛ فئة؛ مثال «شاركت فئةٌ من الدارسين في النشاط».\n\nتطبيق من الحياة اليومية\nعندما تكتب تقريرًا عن مجموعة من الناس استخدم «فئة» كتابة صحيحة وراجع الحركة المحيطة بالهمزة.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يراجع قاعدة الهمزة المكسورة في ثلاثة سياقات.","يصحح أخطاء شائعة في «بئر» و«فئة».","يوظف كلمات بهمزة على نبرة في جمل من إنشائه."],"vocabulary":[{"word":"النبرة","meaning":"شكل الياء الذي تحمل عليه الهمزة"},{"word":"أقوى الحركتين","meaning":"الحركة الأرجح لرسم كرسي الهمزة"}],"quiz":{"prompt":"في أي كلمة كتبت الهمزة المتوسطة على نبرة كتابة صحيحة؟","options":["فئة","فؤة","فأة","فءة"],"correct":"فئة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":33,"title":"القواعد النحوية: الصفة والموصوف","content":"القواعد النحوية: الصفة والموصوف\n\nأهداف التعلّم\n• يعين النعت والمنعوت في جمل قصيرة.\n• يطابق النعت المنعوت في التعريف والتنكير والجنس.\n• يكتب وصفين مناسبين للأشخاص والأشياء.\n\nالشرح التعليمي الأصلي\nالصفة أو النعت تتبع الاسم الموصوف «المنعوت» في الإعراب، والتعريف والتنكير، والجنس، والعدد في النعت الحقيقي المناسب. «قرأت كتابًا مفيدًا»: «كتابًا» منعوت منصوب نكرة، و«مفيدًا» نعت منصوب نكرة. و«المكتبةُ الواسعةُ» صفة معرفة مؤنثة مرفوعة تتبع المكتبة. حين نكتب وصفًا لشخص نفضل صفة موضوعية تتعلق بسلوكه أو عمله، ولا نستخدم الوصف للإساءة إليه.\n\nأمثلة في السياق\n«رسالةٌ واضحةٌ» النعت «واضحةٌ». «الملفُّ المنظمُ» النعت «المنظمُ». يختلف الرسم حسب الاسم الموصوف.\n\nالتدريبات الفردية\nحدد النعت في «اشتريتُ قلمًا جديدًا». صحح «ذهبتُ إلى المدرسةِ الجديدُ». كوّن وصفًا مفيدًا للمركز بكلمتين.\n\nمفتاح الإجابة والتغذية الراجعة\nجديدًا؛ المدرسةِ الجديدةِ؛ مثل «المركزُ المنظمُ» أو «مركزٌ نظيفٌ» بحسب التركيب.\n\nتطبيق من الحياة اليومية\nعند وصف سلعة في إعلان بسيط، اختر صفتين واضحتين يمكن التحقق منهما دون مبالغة.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يعين النعت والمنعوت في جمل قصيرة.","يطابق النعت المنعوت في التعريف والتنكير والجنس.","يكتب وصفين مناسبين للأشخاص والأشياء."],"vocabulary":[{"word":"النعت","meaning":"اسم يبين صفة اسم قبله"},{"word":"المنعوت","meaning":"الاسم الذي تصفه الصفة"}],"quiz":{"prompt":"ما الصفة في «قرأتُ تقريرًا واضحًا»؟","options":["واضحًا","تقريرًا","قرأتُ","لا توجد"],"correct":"واضحًا"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":34,"title":"الإملاء: الهمزة المتوسطة المكسور ما قبلها","content":"الإملاء: الهمزة المتوسطة المكسور ما قبلها\n\nأهداف التعلّم\n• يميّز الكسرة السابقة للهمزة مهما تكن حركة الهمزة.\n• يعلل الرسم على نبرة في «فئة» و«بئر».\n• يصنف كلمتين بحسب حركة الهمزة.\n\nالشرح التعليمي الأصلي\nعندما يكون الحرف السابق للهمزة المتوسطة مكسورًا، فالكسرة أقوى من الضمة والفتحة والسكون، وغالبًا نرسم الهمزة على نبرة «ئ». في «فِئَة» الهمزة مفتوحة بعد كسرة، وفي «بِئْر» الهمزة ساكنة بعد كسرة. أما «مِئَة» فرسمها على ياء أيضًا. نحتاج في الإملاء إلى الاستماع للحركات والكتابة من المعنى، لا إلى تغيير الكلمة لتوافق شكلًا مألوفًا فقط.\n\nأمثلة في السياق\n«فئة» الهمزة مفتوحة بعد كسر الفاء. «بئر» الهمزة ساكنة بعد كسر الباء. كلاهما على نبرة.\n\nالتدريبات الفردية\nضع الهمزة في «فـ_ة» و«بـ_ر». اذكر حركة الهمزة في كل كلمة. اكتب جملة تتضمن «مئة» بعد التأكد من سياقها.\n\nمفتاح الإجابة والتغذية الراجعة\nفئة وبئر؛ همزة فئة مفتوحة، وهمزة بئر ساكنة؛ مثال «قرأت مئة كلمة» مع مراعاة ضوابط العدد في الصياغة.\n\nتطبيق من الحياة اليومية\nراجع كلمة «فئة» عند كتابة وصف لمجموعات المتعلمين، وتجنب تعميم الأحكام على الناس.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميّز الكسرة السابقة للهمزة مهما تكن حركة الهمزة.","يعلل الرسم على نبرة في «فئة» و«بئر».","يصنف كلمتين بحسب حركة الهمزة."],"vocabulary":[{"word":"الحركة السابقة","meaning":"الحركة على الحرف الذي قبل الهمزة"},{"word":"نبرة","meaning":"كرسي الهمزة الشبيه بالياء"}],"quiz":{"prompt":"ما سبب رسم الهمزة على نبرة في «فِئَة»؟","options":["لأن ما قبلها مكسور","لأنها في أول الكلمة","لأن قبلها ضمة فقط","لأنها همزة متطرفة"],"correct":"لأن ما قبلها مكسور"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":35,"title":"القراءة: على شواطئ البحرين - دراسة القصيدة كاملة، والحفظ من 1 إلى 5","content":"القراءة: على شواطئ البحرين - دراسة القصيدة كاملة، والحفظ من 1 إلى 5\n\nأهداف التعلّم\n• يقرأ وصفًا أصليًا لسلوك مسؤول على الشاطئ.\n• يستخرج صورتين مرتبطتين بالبحر.\n• يميز التدريب الأصلي من الأبيات الرسمية المطلوبة للحفظ.\n\nالشرح التعليمي الأصلي\nالعنوان الوارد بالخطة هو «على شواطئ البحرين» ومطلوب دراسة القصيدة كاملة وحفظ الأبيات 1–5. هذه المسودة لا تنقل القصيدة التي لم تُطابق بمصدر الكتاب. بديلها التدريبي المؤقت نص من ضاديوم: «جلس ماجد على الشاطئ وقت الغروب يراقب الموج. سمع صوت الماء ورأى أسرًا تجمع أدواتها قبل المغادرة. التقط ماجد عبوة بلاستيكية آمنة ووضعها في سلة النفايات. أدرك أن البحر مكان للجمال والعمل والمسؤولية». هذا مشهد نثري أصلي، لا أبيات شعرية مقررة.\n\nأمثلة في السياق\nصورتان: حركة الموج وقت الغروب، وصوت الماء. الفكرة: المحافظة على المكان بعد زيارته.\n\nالتدريبات الفردية\nمتى كان ماجد على الشاطئ؟ ما الفعل الذي يدل على مسؤوليته؟ صف صوتًا أو منظرًا بحريًا في جملتين. لا تحفظ هذه الفقرة على أنها جزء من القصيدة الرسمية.\n\nمفتاح الإجابة والتغذية الراجعة\nوقت الغروب؛ وضع العبوة في سلة النفايات؛ يقبل وصف غير منسوخ يوضح المنظر أو الصوت.\n\nتطبيق من الحياة اليومية\nاكتب تنبيهًا قصيرًا لزوار الشاطئ عن جمع المخلفات الآمنة وعدم الاقتراب من أجسام مجهولة أو حادة.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يقرأ وصفًا أصليًا لسلوك مسؤول على الشاطئ.","يستخرج صورتين مرتبطتين بالبحر.","يميز التدريب الأصلي من الأبيات الرسمية المطلوبة للحفظ."],"vocabulary":[{"word":"شاطئ","meaning":"منطقة اليابسة المحاذية للبحر"},{"word":"موج","meaning":"حركة سطح الماء صعودًا وهبوطًا"}],"quiz":{"prompt":"هل النص التدريبي هنا هو قصيدة الكتاب الرسمية؟","options":["لا، هو نص نثري أصلي داعم","نعم هو الأبيات الخمسة","نعم هو فهرس الكتاب","نعم مراجَع رسميًا"],"correct":"لا، هو نص نثري أصلي داعم"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":36,"title":"القواعد النحوية: النفي بـ(ما، لم، لن، لا، ليس)","content":"القواعد النحوية: النفي بـ(ما، لم، لن، لا، ليس)\n\nأهداف التعلّم\n• يميّز أدوات النفي الخمس بحسب الجملة.\n• يضبط المضارع الصحيح بعد «لم» و«لن».\n• يصوغ نفيًا واضحًا لموقف في الماضي أو المستقبل.\n\nالشرح التعليمي الأصلي\nالنفي ينكر وقوع الحدث أو ثبوت الصفة. «ما حضرتُ أمس» لنفي حدث ماضٍ في سياق مناسب؛ «لم أحضرْ أمس» فيها «لم» تجزم المضارع وتحوّل معناه إلى الماضي. «لن أتأخرَ غدًا» تنصب المضارع وتنفي المستقبل. «لا أهملُ العمل» نفي عادة مع مضارع مرفوع، بينما «لا تهملْ» نهي يجزم المضارع. «ليس الموعدُ بعيدًا» فعل ناسخ ينفي الجملة الاسمية، ويرفع اسمه وينصب خبره.\n\nأمثلة في السياق\nلم أسافرْ أمس؛ لن أسافرَ غدًا؛ ليس المكانُ بعيدًا؛ لا أنسى الموعدَ. نراقب المعنى والزمن والإعراب.\n\nالتدريبات الفردية\nاختر بين لم ولن: «___ أخرجْ أمس». اضبط «لن أترك ... الدراسة». صحح «ليس الطريقَ طويلٌ».\n\nمفتاح الإجابة والتغذية الراجعة\n«لم أخرجْ أمس»؛ «لن أتركَ الدراسة»؛ «ليس الطريقُ طويلًا».\n\nتطبيق من الحياة اليومية\nاكتب اعتذارًا مختصرًا ينفي تأخرك في موعد سابق، ووعدًا للمستقبل مستخدمًا «لن».\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميّز أدوات النفي الخمس بحسب الجملة.","يضبط المضارع الصحيح بعد «لم» و«لن».","يصوغ نفيًا واضحًا لموقف في الماضي أو المستقبل."],"vocabulary":[{"word":"نفي","meaning":"إنكار وقوع الفعل أو ثبوت الصفة"},{"word":"نهي","meaning":"طلب التوقف عن فعل"}],"quiz":{"prompt":"أي جملة تنفي فعلًا مستقبليًا؟","options":["لن أتأخرَ غدًا","لم أتأخرْ أمس","حضرتُ اليوم","اكتبْ الآن"],"correct":"لن أتأخرَ غدًا"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":37,"title":"القراءة: الكلب والحمامة - دراسة القصيدة كاملة، والحفظ من 1 إلى 5","content":"القراءة: الكلب والحمامة - دراسة القصيدة كاملة، والحفظ من 1 إلى 5\n\nأهداف التعلّم\n• يستنتج قيمة المساعدة من حكاية أصلية مستقلة.\n• يرتب أحداث الحكاية من البداية للنهاية.\n• يفرق بين قصة تدريبية والقصيدة الرسمية التي تنتظر التحقق.\n\nالشرح التعليمي الأصلي\nتورد الخطة قصيدة «الكلب والحمامة» لدراستها كاملة وحفظ الأبيات 1–5. لا نعرض هنا أبياتًا غير موثقة أو نزعم أنها الأصل. الحكاية الآتية من تأليف ضاديوم للتدرب على الفهم: «رأت حمامة كلبًا عطشان قرب حديقة. انتبه صاحب الحديقة إلى الكلب فوضع له وعاء ماء نظيفًا بعيدًا عن الطريق. ارتاحت الحمامة فوق الشجرة، وشكر صاحب الحديقة زواره على مساعدتهم». لا تؤنسن الحيوانات على أنها تتكلم بالفعل؛ المطلوب استنتاج قيمة الرفق وتحديد دور الإنسان المسؤول.\n\nأمثلة في السياق\nبداية: كلب عطشان. استجابة: صاحب الحديقة وفر الماء. نتيجة: زالت المشكلة بطريقة آمنة. قيمة: الرحمة بالحيوان.\n\nالتدريبات الفردية\nمن الذي وضع الماء؟ ماذا كانت مشكلة الكلب؟ اكتب حكاية من أربع جمل عن مساعدة مخلوق دون الاقتراب من حيوان مجهول. انتظر الكتاب للتحقق من النص الشعري المطلوب حفظه.\n\nمفتاح الإجابة والتغذية الراجعة\nصاحب الحديقة؛ العطش؛ تقبل حكاية لها مشكلة وحل ونتيجة مع مراعاة السلامة.\n\nتطبيق من الحياة اليومية\nإذا لاحظت حيوانًا يحتاج مساعدة، أخبر المسؤول أو الجهة المختصة بدل ملامسته إن كان مجهولًا أو عدوانيًا.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يستنتج قيمة المساعدة من حكاية أصلية مستقلة.","يرتب أحداث الحكاية من البداية للنهاية.","يفرق بين قصة تدريبية والقصيدة الرسمية التي تنتظر التحقق."],"vocabulary":[{"word":"الرفق","meaning":"التعامل بلطف ورحمة"},{"word":"تسلسل","meaning":"ترتيب الأحداث بحسب وقوعها"}],"quiz":{"prompt":"من الذي قدّم الماء للكلب في حكاية ضاديوم؟","options":["صاحب الحديقة","الحمامة","الكلب الآخر","سائق الحافلة"],"correct":"صاحب الحديقة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":38,"title":"الإملاء: الهمزة المتطرفة المكسور ما قبلها","content":"الإملاء: الهمزة المتطرفة المكسور ما قبلها\n\nأهداف التعلّم\n• يتعرف الهمزة المتطرفة في نهاية الكلمات.\n• يرسم الهمزة على ياء عندما يسبقها كسر.\n• يكتب «شاطئ» و«قارئ» و«هادئ» بصورة صحيحة.\n\nالشرح التعليمي الأصلي\nالهمزة المتطرفة تقع في آخر الكلمة، ويعتمد كرسيها على حركة الحرف الذي قبلها، لا على حركة الهمزة نفسها. إذا كان السابق مكسورًا كتبت الهمزة على ياء «ئ»: «شاطِئ»، «قارِئ»، «هادِئ». إذا كان السابق مضمومًا قد تكون على واو مثل «تباطُؤ»، وإذا كان مفتوحًا على ألف مثل «ملجَأ». نحدد الحركة السابقة قبل كتابة الكلمة.\n\nأمثلة في السياق\n«القارئُ هادئٌ» فيها كلمتان آخرهما همزة على ياء: قارئ، هادئ. «على شاطئ البحر» كذلك.\n\nالتدريبات الفردية\nأكمل «قار_» و«هاد_» و«شاط_». ما حركة الحرف قبل الهمزة؟ اكتب جملة تحتوي كلمتين من الثلاث.\n\nمفتاح الإجابة والتغذية الراجعة\nقارئ، هادئ، شاطئ؛ الحركة الكسرة؛ مثال «جلس قارئٌ هادئٌ قرب الشاطئ».\n\nتطبيق من الحياة اليومية\nراجع رسم «شاطئ» عند كتابة إعلان لنشاط بيئي، ولا تكتبها بهمزة منفصلة عن كرسيها.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يتعرف الهمزة المتطرفة في نهاية الكلمات.","يرسم الهمزة على ياء عندما يسبقها كسر.","يكتب «شاطئ» و«قارئ» و«هادئ» بصورة صحيحة."],"vocabulary":[{"word":"متطرفة","meaning":"همزة في نهاية الكلمة"},{"word":"كرسي الياء","meaning":"شكل يحمل الهمزة عندما يناسب الكسرة"}],"quiz":{"prompt":"أي رسم صحيح لكلمة تدل على قارئ الكتب؟","options":["قارئ","قارء","قارؤ","قارأ"],"correct":"قارئ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":39,"title":"الإنتاج الكتابي: بطاقة الدعوة (1) و(2)","content":"الإنتاج الكتابي: بطاقة الدعوة (1) و(2)\n\nأهداف التعلّم\n• يحدد الغرض والمكان والموعد في بطاقة دعوة.\n• يختار تحية مناسبة للمدعو.\n• ينشئ بطاقة مختصرة لا تتضمن معلومات غير مؤكدة.\n\nالشرح التعليمي الأصلي\nبطاقة الدعوة نص قصير يطلب حضور شخص إلى مناسبة أو نشاط. يجب أن يظهر فيها نوع المناسبة، واسم الجهة أو صاحب الدعوة، والموعد، والمكان، ووسيلة للاستفسار عند الحاجة. مثال تدريبي: «يسرّ مركز التعلم دعوتكم إلى لقاء القراءة يوم الخميس الساعة الخامسة مساءً في القاعة العامة. الرجاء تأكيد الحضور». هذه بيانات افتراضية ينبغي استبدالها بالبيانات الحقيقية قبل الاستخدام؛ لا ندّعي إقامة حدث فعلي.\n\nأمثلة في السياق\nالجهة الداعية: المركز. المناسبة: لقاء القراءة. المكان: القاعة العامة. اليوم والساعة محددان بوضوح في المثال الافتراضي.\n\nالتدريبات الفردية\nاستخرج موعد اللقاء من المثال. ما المعلومات الناقصة إذا كتبت «يسرنا حضوركم» وحدها؟ صمم بطاقة من خمسة أسطر لنشاط تخيلي مع توضيح أنه مثال تعليمي.\n\nمفتاح الإجابة والتغذية الراجعة\nالموعد الخميس الخامسة مساءً؛ تنقص المناسبة والمكان والتوقيت والجهة؛ تقبل بطاقة دقيقة التنظيم لا تدّعي إعلانًا حقيقيًا.\n\nتطبيق من الحياة اليومية\nعند تلقي دعوة حقيقية راجع التاريخ والمكان واسم الجهة من مصدر موثوق قبل مشاركتها.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يحدد الغرض والمكان والموعد في بطاقة دعوة.","يختار تحية مناسبة للمدعو.","ينشئ بطاقة مختصرة لا تتضمن معلومات غير مؤكدة."],"vocabulary":[{"word":"مدعو","meaning":"الشخص المطلوب حضوره"},{"word":"تأكيد الحضور","meaning":"إبلاغ الجهة بالموافقة على المشاركة"}],"quiz":{"prompt":"أي معلومة ضرورية في بطاقة الدعوة؟","options":["موعد المناسبة ومكانها","خاتمة قصة طويلة","رقم لا علاقة له بالمناسبة","اسم غير صحيح"],"correct":"موعد المناسبة ومكانها"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":40,"title":"القواعد النحوية: العطف بـ(الواو، ثم، أو)","content":"القواعد النحوية: العطف بـ(الواو، ثم، أو)\n\nأهداف التعلّم\n• يميز دلالة الواو وثم وأو في سياقات متنوعة.\n• يحدد المعطوف والمعطوف عليه.\n• يكتب ثلاث جمل تربط أحداثًا واختيارات.\n\nالشرح التعليمي الأصلي\nالعطف يربط بين كلمات أو جمل بحرف مناسب. «زار سالمٌ المكتبةَ والمركزَ» الواو تفيد المشاركة ولا يلزم منها ترتيب زمني. «قرأتُ التعليماتِ ثم وقّعتُ» تفيد ثم الترتيب مع تراخٍ مناسب للسياق. «اشرب ماءً أو عصيرًا» تعرض اختيارًا بين أمرين. المعطوف يتبع المعطوف عليه في الإعراب في عطف المفردات، فلا نهمل الحركة عند التدريب.\n\nأمثلة في السياق\n«سالمٌ وأحمدُ» مشاركة. «أنهيتُ التمرين ثم راجعته» ترتيب. «دفترٌ أو ورقةٌ» اختيار.\n\nالتدريبات الفردية\nاختر الحرف المناسب «راجعتُ البيانات ___ أرسلتُ الطلب» عندما تريد الترتيب. صنف جملة «الشاي أو القهوة». كوّن جملة بالواو دون قصد الترتيب.\n\nمفتاح الإجابة والتغذية الراجعة\nثم؛ اختيار؛ مثال «حضر خالدٌ وسالمٌ اللقاءَ» والواو لا تثبت ترتيب الحضور.\n\nتطبيق من الحياة اليومية\nاكتب تعليمات من خطوتين باستخدام «ثم»، وقائمة اختيار من بديلين باستخدام «أو».\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز دلالة الواو وثم وأو في سياقات متنوعة.","يحدد المعطوف والمعطوف عليه.","يكتب ثلاث جمل تربط أحداثًا واختيارات."],"vocabulary":[{"word":"المعطوف","meaning":"اسم أو جملة يربطها حرف عطف بما قبلها"},{"word":"تراخٍ","meaning":"وجود مهلة أو فاصل بين حدثين"}],"quiz":{"prompt":"أي حرف أنسب لبيان ترتيب حدثين مع مهلة؟","options":["ثم","أو","الواو دون قرينة","هل"],"correct":"ثم"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":41,"title":"الإنتاج الكتابي: بطاقة الدعوة (3)","content":"الإنتاج الكتابي: بطاقة الدعوة (3)\n\nأهداف التعلّم\n• يراجع بطاقة دعوة ويصحح نقصًا فيها.\n• يميز الإعلان المؤكد من الدعوة التدريبية.\n• يكتب نسخة نهائية موجزة بعد مراجعة الوقت والعنوان.\n\nالشرح التعليمي الأصلي\nبعد إعداد بطاقة الدعوة نراجع صحتها ووضوحها قبل إرسالها. نتحقق من اسم النشاط، والجهة الداعية، والتاريخ باليوم والسنة عند الحاجة، والوقت والمنطقة الزمنية إن كان اللقاء عن بعد، والمكان أو الرابط الرسمي. مثال غير مكتمل «لقاء الخميس في المركز» قد يربك القارئ؛ ننقحه بإضافة عنوان القاعة والساعة والجهة. نحذف روابط غير موثقة وبيانات حساسة، ولا نستخدم صيغة تأكيد حدث غير معتمد.\n\nأمثلة في السياق\nبطاقة ناقصة: «ندعوكم إلى اللقاء». البطاقة المحسنة: «يدعوكم نادي القراءة إلى جلسة تدريبية افتراضية يوم الخميس الساعة الخامسة مساءً وفق توقيت البحرين»، مع إضافة الرابط المعتمد عند توفره.\n\nالتدريبات الفردية\nاكتب ثلاثة أوجه نقص في البطاقة الأولى. راجع بطاقة أنتجتها في الدرس السابق. تحقق من ترتيب المعلومات وصحة الكلمات التي تحتوي همزات.\n\nمفتاح الإجابة والتغذية الراجعة\nتنقص المناسبة والموعد والمكان أو الرابط والجهة الداعية؛ تقبل بطاقة نهائية مستوفية لهذه البنود مع توضيح أن بيانات المثال افتراضية.\n\nتطبيق من الحياة اليومية\nراجع دعوة حقيقية في هاتفك قبل إعادة توجيهها، خاصة اسم الجهة والتوقيت والرابط.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يراجع بطاقة دعوة ويصحح نقصًا فيها.","يميز الإعلان المؤكد من الدعوة التدريبية.","يكتب نسخة نهائية موجزة بعد مراجعة الوقت والعنوان."],"vocabulary":[{"word":"تنقيح","meaning":"تحسين النص بعد المراجعة"},{"word":"رابط معتمد","meaning":"رابط ثبتت صحته من الجهة الداعية"}],"quiz":{"prompt":"ما الذي يجب فعله قبل إرسال دعوة تحتوي رابط حضور؟","options":["التحقق من الرابط لدى الجهة المنظمة","نسخ أي رابط مجهول","حذف وقت اللقاء","إخفاء اسم الجهة"],"correct":"التحقق من الرابط لدى الجهة المنظمة"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":42,"title":"الإملاء: الهمزة المتطرفة المسبوقة بحرف ساكن صحيح أو حرف علة","content":"الإملاء: الهمزة المتطرفة المسبوقة بحرف ساكن صحيح أو حرف علة\n\nأهداف التعلّم\n• يميز الساكن الصحيح من حرف المد قبل الهمزة المتطرفة.\n• يرسم الهمزة على السطر في «جزء» و«شيء».\n• يقارن مع همزة آخر «قارئ» بعد كسرة.\n\nالشرح التعليمي الأصلي\nتكتب الهمزة المتطرفة على السطر إذا سبقها حرف ساكن لا حركة له، مثل «جُزْء» حيث الزاي ساكنة، أو سبقها حرف مد مثل «ماء» و«هدوء» و«شيء» التي فيها الياء ساكنة. أما «قارئ» فالراء مكسورة، ولذلك كتبت الهمزة على ياء. لا نضيف كرسِيًا للهمزة المتطرفة بعد ساكن لمجرد أنها تأتي بعد حرف في الرسم، بل نفحص حركة ما قبلها بدقة.\n\nأمثلة في السياق\n«جزء» الهمزة على السطر بعد زاي ساكنة. «ماء» على السطر بعد ألف مد. «قارئ» على ياء بعد راء مكسورة.\n\nالتدريبات الفردية\nاكمل «جز_» و«ما_» و«قار_». لماذا اختلف كرسي الهمزة الأخيرة في «قارئ»؟ اكتب جملة بكلمة «شيء» من حياتك.\n\nمفتاح الإجابة والتغذية الراجعة\nجزء، ماء، قارئ؛ لأن ما قبل همزة قارئ مكسور، أما جزء وماء فقبلهما ساكن أو مد.\n\nتطبيق من الحياة اليومية\nفي ملاحظات العمل، اكتب «جزء» و«شيء» بوضوح، وراجع آخر الكلمة قبل الإرسال.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يميز الساكن الصحيح من حرف المد قبل الهمزة المتطرفة.","يرسم الهمزة على السطر في «جزء» و«شيء».","يقارن مع همزة آخر «قارئ» بعد كسرة."],"vocabulary":[{"word":"ساكن صحيح","meaning":"حرف صحيح لا حركة قصيرة عليه"},{"word":"حرف مد","meaning":"ألف أو واو أو ياء تمد الصوت وفق شرطها"}],"quiz":{"prompt":"أي كلمة كتبت همزتها المتطرفة على السطر بعد ساكن؟","options":["جزء","قارئ","ملجأ","لؤلؤ"],"correct":"جزء"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false},{"order":43,"title":"مراجعة عامة","content":"مراجعة عامة\n\nأهداف التعلّم\n• يربط بين نحو الجملة والإملاء والقراءة الوظيفية.\n• يصحح نصًا قصيرًا متعدد الأخطاء.\n• ينتج رسالة أو تقريرًا منظمًا مستعينًا بما تعلمه.\n\nالشرح التعليمي الأصلي\nهذه مراجعة تجمع أهم المهارات التي تدرب عليها الدارس في المستوى: تحديد الفاعل والمفعول به، وضبط المبتدأ والخبر، والتمييز بين «كان» و«إن»، واختيار حرف الجر، ورسم الهمزة، وكتابة الرسالة والتقرير والدعوة. في نص تدريبي: «قرأَ الموظفُ الرسالةَ، ثم كتب تقريرًا واضحًا. إنَّ العملَ منظّمٌ عندما تكون البيانات دقيقة». نحدد فعلًا وفاعلًا ومفعولًا، ونلاحظ العطف بـ«ثم»، ونراجع اسم إن وخبرها دون تعميم أحكام خاطئة.\n\nأمثلة في السياق\nفي «قرأ الموظف الرسالة» الفاعل الموظفُ والمفعول الرسالةَ. «إن العمل منظّم» عملَ اسم إن ومنظمٌ خبرها. «ثم» يدل على الترتيب.\n\nالتدريبات الفردية\nحلّل جملة «أرسلَ الدارسُ رسالةً قصيرةً». اختر الشكل الصحيح «قارئ/قارء». اكتب بطاقة دعوة افتراضية من أربعة أسطر ثم راجع بياناتها ولغتها.\n\nمفتاح الإجابة والتغذية الراجعة\nالفاعل الدارسُ؛ المفعول رسالةً والنعت قصيرةً؛ «قارئ»؛ تقبل بطاقة تبين الغرض والجهة والزمان والمكان.\n\nتطبيق من الحياة اليومية\nحدّد مهارتين تحتاج إلى ممارسة إضافية وضع خطة قصيرة للأسبوع القادم، مع الاستعانة بمعلمك في مراجعة الكتاب الرسمي.\n\nالتوثيق: محتوى تعليمي مستقل من تأليف ضاديوم مرتبط بعنوان وارد في خطة التعليم المستمر البحرينية 2026–2027، وليس نقلًا عن متن الكتاب أو دليلًا على مطابقة فهرسه. الأبيات الشعرية الرسمية وأرقام الحفظ تنتظر الرجوع إلى الكتاب والتحقق منه. المراجعة التربوية النهائية لازمة.\nSOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1","learning_objectives":["يربط بين نحو الجملة والإملاء والقراءة الوظيفية.","يصحح نصًا قصيرًا متعدد الأخطاء.","ينتج رسالة أو تقريرًا منظمًا مستعينًا بما تعلمه."],"vocabulary":[{"word":"مراجعة تراكمية","meaning":"تدريب يجمع عدة مهارات"},{"word":"تقويم ذاتي","meaning":"تحديد ما أتقنته وما أحتاج تحسينه"}],"quiz":{"prompt":"ما الفاعل في «قرأَ الموظفُ الرسالةَ»؟","options":["الموظفُ","الرسالةَ","قرأَ","لا يوجد"],"correct":"الموظفُ"},"origin":"DADYOOM_BH_FOLLOWUP1_DRAFT_V1","editorialReview":"required","bookTextCopied":false}]$PAYLOAD$::jsonb))
INSERT INTO public.lesson_activities (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
SELECT l.id,'تدريب فهم أصلي من ضاديوم','multiple_choice',
 'اختر الإجابة الصحيحة، ثم حاول تفسير اختيارك. المحتوى داعم يحتاج المراجعة التربوية.',
 jsonb_build_object('origin','DADYOOM_BH_FOLLOWUP1_MCQ_V1','options',p.j->'quiz'->'options','editorial_review','required','book_text_copied',false),
 1,5,true,'assessment',p.j->'quiz'->>'prompt',jsonb_build_object('correct',p.j->'quiz'->>'correct'),false
FROM payload p JOIN public.lessons l ON l.title=p.j->>'title' AND l.content LIKE '%SOURCE=DADYOOM_BH_FOLLOWUP1_DRAFT_V1%'
JOIN public.units u ON u.id=l.unit_id AND u.semester=1
JOIN public.grades g ON g.id=u.grade_id AND g.name_ar='الأول متابعة' AND g.grade_number IS NULL
JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
JOIN public.countries co ON co.id=cu.country_id AND co.code='BH'
WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.content->>'origin'='DADYOOM_BH_FOLLOWUP1_MCQ_V1');